const item = $input.item.json;
const avaliacoes = (item.avaliacoes_texto || []).slice(0, 50).join('\n- ');
const instaBio = item.instagram_bio || '';
const siteAtualCopy = item.site_atual_copy || '';

const prompt = `Você é um estrategista de marca para pequenos negócios locais. Com base nos dados abaixo de um ${item.tem_site_existente ? 'negócio que já tem site' : 'negócio que ainda não tem site'} do nicho "${item.nicho || 'não informado'}", em ${item.regiao || 'região não informada'}, gere um briefing estruturado em JSON puro (sem markdown, sem texto fora do JSON) com exatamente estas chaves:
{
  "tom_de_voz": string,
  "paleta_sugerida": [string, string, string],
  "proposta_de_valor": string,
  "nome": string,
  "telefone": string,
  "email": string,
  "redes_sociais": { "instagram": string },
  "padrao_de_dor": string
}

Dados do negócio:
- Nicho: ${item.nicho || ''}
- Região: ${item.regiao || ''}
- Nome: ${item.nome || ''}
- Telefone: ${item.telefone || ''}
- Email: ${item.email || ''}
- Instagram: ${item.instagram_handle || ''}
- Bio do Instagram: ${instaBio}
- Nota Google: ${item.nota_google || ''}
- Avaliações do Google (texto bruto, extrair padrão de dor/elogio real, não inventar):
- ${avaliacoes}
${item.tem_site_existente ? '- Conteúdo do site atual (preservar identidade, não recomeçar do zero):\n' + siteAtualCopy : ''}

O campo "padrao_de_dor" deve vir das avaliações reais, não de suposição genérica. Se não houver avaliações suficientes, diga isso explicitamente no campo em vez de inventar. O "tom_de_voz" e a "proposta_de_valor" devem refletir o nicho informado, não um tom genérico — cada nicho tem convenções diferentes (ex.: advocacia/clínica pedem tom mais formal e cuidado regulatório; salão/oficina podem ser mais próximos e informais).`;

item._prompt_briefing = prompt;
return { json: item };

// Extrai o JSON do texto retornado pela Claude API e funde com os dados originais do lead.
const response = $input.item.json;
const original = $('Montar prompt do briefing').item.json;
const text = response.content && response.content[0] ? response.content[0].text : '{}';

let briefing;
try {
  const match = text.match(/\{[\s\S]*\}/);
  briefing = JSON.parse(match ? match[0] : text);
} catch (e) {
  briefing = { erro_parse: true, texto_bruto: text };
}

const merged = { ...original, briefing };
delete merged._prompt_briefing;
return { json: merged };
